<?php

declare(strict_types=1);

namespace Papercut\Math;

/**
 * The MathML Core operator dictionary (resources/operators.php, generated by bin/gen-operators.php).
 * Spacing is in 1/18 em. Opening and closing fences are listed here by hand because Core marks `|` and `‖`
 * as fences in both prefix and postfix form, which is not what the form resolver wants.
 *
 * @internal Part of papercut/math's engine, not its public API. It may change in any release.
 */
final class OperatorDictionary
{
    public const FORM_PREFIX = 'prefix';
    public const FORM_INFIX = 'infix';
    public const FORM_POSTFIX = 'postfix';

    private const DEFAULT_SPACE = 5;

    /** @var array<string, array{form: string, lspace: int, rspace: int, stretchy: bool, symmetric: bool, largeop: bool, movablelimits: bool, fence: bool}>|null */
    private static ?array $table = null;

    private const OPEN = '([{⟨⌈⌊⟪';
    private const CLOSE = ')]}⟩⌉⌋⟫';

    public static function isOpening(string $ch): bool
    {
        return $ch !== '' && mb_strpos(self::OPEN, $ch) !== false;
    }

    public static function isClosing(string $ch): bool
    {
        return $ch !== '' && mb_strpos(self::CLOSE, $ch) !== false;
    }

    /**
     * The dictionary entry for an operator in a form. A form with no entry falls back to infix, then
     * postfix, then prefix; a character with no entry at all gets 5/18 em on each side.
     *
     * @return array{lspace: int, rspace: int, stretchy: bool, symmetric: bool, largeop: bool, movablelimits: bool}
     */
    public static function lookup(string $char, string $form): array
    {
        self::$table ??= require __DIR__ . '/../resources/operators.php';
        foreach ([$form, self::FORM_INFIX, self::FORM_POSTFIX, self::FORM_PREFIX] as $f) {
            $e = self::$table[$char . '|' . $f] ?? null;
            if ($e !== null) {
                return [
                    'lspace' => $e['lspace'],
                    'rspace' => $e['rspace'],
                    'stretchy' => $e['stretchy'],
                    'symmetric' => $e['symmetric'],
                    'largeop' => $e['largeop'],
                    'movablelimits' => $e['movablelimits'],
                ];
            }
        }

        return [
            'lspace' => self::DEFAULT_SPACE,
            'rspace' => self::DEFAULT_SPACE,
            'stretchy' => false,
            'symmetric' => false,
            'largeop' => false,
            'movablelimits' => false,
        ];
    }

    /**
     * True when the operator takes relation or binary spacing, which TeX (and we) drop in script styles: its infix
     * entry has space on both sides. A character with no entry in any form gets the default space on both sides, so
     * it counts too; one that only has prefix or postfix entries (a fence, a big operator) does not.
     */
    public static function dropsSpacingInScripts(string $ch): bool
    {
        self::$table ??= require __DIR__ . '/../resources/operators.php';
        $infix = self::$table[$ch . '|' . self::FORM_INFIX] ?? null;
        if ($infix !== null) {
            return $infix['lspace'] > 0 && $infix['rspace'] > 0;
        }

        return ! isset(self::$table[$ch . '|' . self::FORM_PREFIX]) && ! isset(self::$table[$ch . '|' . self::FORM_POSTFIX]);
    }
}
